@Test
void hostCommitBindsIndependentCommandAndEventWatermarks() {
    var commandBefore = new CanonicalFacts.CommandWatermark(SESSION, 7);
    var command = new CanonicalFacts.AcceptedCommand(SESSION, "command-8", 8, HASH, "result-8");
    var commandAfter = commandBefore.append(command);
    var deliveryBefore = new CanonicalFacts.DeliveryWatermark(SESSION, 11, 1, 9, 4);
    var events = List.of(
            new CanonicalFacts.DurableDelivery(SESSION, 12, 5, "session.updated", HASH),
            new CanonicalFacts.DurableDelivery(SESSION, 13, 5, "queue.updated", HASH));
    var deliveryAfter = deliveryBefore.append(events);
    var commit = new CanonicalFacts.HostCommit(
            Optional.of(command), commandBefore, commandAfter,
            new CanonicalFacts.FollowUpQueue(3, List.of()),
            new CanonicalFacts.AgentSessionLog(List.of(), 1),
            events, deliveryBefore, deliveryAfter, 5);
    assertEquals(8, commit.commandAfter().lastAcceptedSeq());
    assertEquals(13, commit.deliveryAfter().lastEventSeq());
}

@Test
void effectOnlyCommitDoesNotAdvanceAcceptedSequence() {
    var command = new CanonicalFacts.CommandWatermark(SESSION, 8);
    var deliveryBefore = new CanonicalFacts.DeliveryWatermark(SESSION, 13, 1, 9, 4);
    var events = List.of(new CanonicalFacts.DurableDelivery(SESSION, 14, 6, "tool.completed", HASH));
    var commit = new CanonicalFacts.HostCommit(
            Optional.empty(), command, command,
            new CanonicalFacts.FollowUpQueue(3, List.of()),
            new CanonicalFacts.AgentSessionLog(List.of(), 1),
            events, deliveryBefore, deliveryBefore.append(events), 6);
    assertEquals(8, commit.commandAfter().lastAcceptedSeq());
    assertEquals(14, commit.deliveryAfter().lastEventSeq());
}

